// Independent Rust Vec concatenation with standard owned copies and transfers.
type String=std::borrow::Cow<'static,str>;
#[derive(Clone)]struct Record0{field0:i64,field1:String,field2:Vec<Record0>}
fn function0(value0: i64, value1: i64, value2: &String) -> Vec<Vec<Record0>> {let base=vec![Record0{field0:value1,field1:String::Owned(value2.to_string()),field2:vec![Record0{field0:1,field1:String::Borrowed("é"),field2:vec![]}]},Record0{field0:2,field1:String::Borrowed("😀"),field2:vec![]},Record0{field0:3,field1:String::Borrowed("a\0b"),field2:vec![Record0{field0:4,field1:String::Borrowed("e\u{301}"),field2:vec![]}]},Record0{field0:5,field1:String::Borrowed("x"),field2:vec![]},Record0{field0:6,field1:String::Borrowed("z"),field2:vec![]}];let mut output=Vec::with_capacity(usize::try_from(value0).unwrap());for i in 0..value0{let mode=i.checked_add(value1).unwrap()%4;let count=[0_usize,1,4,5][usize::try_from(mode).unwrap()];let selected=base[..count].to_vec();let first=base[1..usize::try_from(mode%3+2).unwrap()].to_vec();let second=base[..usize::try_from(mode%2).unwrap()].to_vec();let empty:Vec<Record0>=Vec::new();let scalar0=Record0{field0:value1.checked_add(i).unwrap(),field1:String::Owned(value2.to_string()),field2:vec![Record0{field0:i,field1:String::Borrowed("e\u{301}"),field2:vec![]}]};let scalar1=Record0{field0:i,field1:String::Borrowed("a\0b"),field2:vec![]};let mut result=selected;result.push(scalar0);result.extend(first);result.push(scalar1);result.extend(empty);result.extend(second);output.push(result);}output}
